require __DIR__.'/bootstrap.php';if(empty($_SESSION['admin_id']))redirect('index.php');require_once dirname(__DIR__).'/private/mail_service.php';require_once dirname(__DIR__).'/private/mail_engine.php';require_once dirname(__DIR__).'/private/ui.php';require_once dirname(__DIR__).'/private/mail_ui.php';
$id=(int)($_GET['id']??0);$folder=(string)($_GET['folder']??'INBOX');$filter=in_array($_GET['f']??'',['unread','important'],true)?(string)$_GET['f']:'';$search=mb_substr(trim((string)($_GET['q']??'')),0,100);$page=max(1,min(10000,(int)($_GET['page']??1)));
$listUrl=static fn(array $over=[])=>'mail.php?'.http_build_query(array_filter(array_replace(['folder'=>$folder,'f'=>$filter,'q'=>$search],$over),fn($v,$k)=>$v!==''&&$v!==null&&!($k==='page'&&(int)$v<2),ARRAY_FILTER_USE_BOTH));
