 elseif($action==='assign'){$values=[];foreach(['property_id'=>'properties','customer_id'=>'customers'] as $field=>$table){$value=(int)($_POST[$field]??0);if($value){$q=$pdo->prepare('SELECT id FROM '.$table.' WHERE id=?');$q->execute([$value]);if(!$q->fetchColumn())throw new InvalidArgumentException('Zuordnung nicht gefunden.');}$values[]=$value?:null;}$pdo->prepare('UPDATE mail_messages SET property_id=?,customer_id=? WHERE id=?')->execute([...$values,$id]);gszAudit($pdo,$admin,'mail_assignment',['message_id'=>$id]);$_SESSION['app_notice']=$values[0]||$values[1]?'Zugeordnet.':'Zuordnung entfernt.';}
 elseif($action==='task'){require_once dirname(__DIR__).'/private/operations.php';require_once dirname(__DIR__).'/private/scheduler.php';$m=gszMailMessage($pdo,$id);$title=mb_substr(trim((string)($_POST['title']??'')),0,190);if($title==='')throw new InvalidArgumentException('Bitte einen Titel eingeben.');$date=(string)($_POST['due_date']??'');if($date!==''&&!zgsValidDate($date))throw new InvalidArgumentException('Datum ungültig.');$property=(int)($_POST['property_id']??0);
  $note=mb_substr('Aus Mail von '.gszMailName((string)$m['sender']).' ('.gszMailWhen($m['sent_at'],true).'): '.$m['subject'],0,5000);$task=opsSaveTask($pdo,$admin,[$title,$date?:null,$note,null,null,'normal',0,null,null],$property,0,false,null);
  $pdo->prepare('UPDATE mail_messages SET task_id=?,property_id=COALESCE(property_id,?) WHERE id=?')->execute([$task,$property?:null,$id]);gszAudit($pdo,$admin,'mail_assignment',['message_id'=>$id,'task_id'=>$task]);$_SESSION['app_notice']='Aufgabe angelegt'.($date?' für den '.(new DateTimeImmutable($date))->format('d.m.'):'').'.';}
 elseif($action==='rule'){$pattern=trim((string)($_POST['pattern']??''));if($pattern===''||mb_strlen($pattern)>190)throw new InvalidArgumentException('Absender: 1–190 Zeichen.');$pdo->prepare('INSERT INTO mail_rules(sender_pattern,important) VALUES(?,?)')->execute([$pattern,isset($_POST['important'])?1:0]);}
