if($_SERVER['REQUEST_METHOD']==='GET'&&!$id&&$folder==='INBOX'){try{require_once dirname(__DIR__).'/private/automation.php';$auto=gszAutomationOnOpen($pdo,$config,'mail');if(($auto['status']??'')==='PASS'&&($auto['result']['created']??0)>0)$_SESSION['app_notice']=$auto['result']['created']===1?'1 neue Mail.':$auto['result']['created'].' neue Mails.';}catch(Throwable $e){}}
