 $where=' FROM mail_messages m JOIN mail_folders f ON f.id=m.folder_id LEFT JOIN properties p ON p.id=m.property_id WHERE f.name=? AND m.active=1'.($filter==='unread'?' AND m.seen=0':'').($filter==='important'?' AND m.important=1 AND m.answered=0':'').($search!==''?' AND (m.subject LIKE ? OR m.sender LIKE ? OR m.body LIKE ?)':'');$args=[$folder,...($search!==''?array_fill(0,3,'%'.$search.'%'):[])];
 $q=$pdo->prepare('SELECT COUNT(*)'.$where);$q->execute($args);$total=(int)$q->fetchColumn();$q=$pdo->prepare('SELECT m.id,m.sender,m.subject,m.sent_at,m.seen,m.important,m.answered,m.task_id,LEFT(m.body,600) preview,p.name property_name'.$where.' ORDER BY COALESCE(m.sent_at,m.created_at) DESC,m.id DESC LIMIT 30 OFFSET '.(($page-1)*30));$q->execute($args);$messages=$q->fetchAll();
}catch(Throwable $e){$ready=false;$_SESSION['app_error']='Mail-Datenmodell nicht bereit. Gesamtstand-Migration ausführen.';}
